    child = qdict_get(vnc, "acl");

    g_assert_cmpint(qobject_type(child), ==, QTYPE_QDICT);

    acl = qdict_get_qdict(vnc, "acl");

    g_assert_cmpstr("acl0", ==, qdict_get_str(acl, "rule.name"));



    QDECREF(src);

    QDECREF(dst);

}


