        os->nb_chapters++;

        os->chapters = av_realloc(os->chapters, sizeof(AVChapter) * os->nb_chapters);

        if (!os->chapters)

            return AVERROR(ENOMEM);

        os->chapters[os->nb_chapters - 1] = out_ch;

    }

    return 0;

}


