{

    int ret;



    av_log(s->avctx, AV_LOG_DEBUG, "reinit context\n");



    /* 1. streamoff */

    ret = ff_v4l2_context_set_status(&s->capture, VIDIOC_STREAMOFF);

    if (ret)

        av_log(s->avctx, AV_LOG_ERROR, "capture VIDIOC_STREAMOFF\n");



