{

#ifdef CONFIG_LINUX

    char buf[32];

    const char *end;

    char *sysfspath;

    int ret;

    int fd = -1;

    long max_segments;



    sysfspath = g_strdup_printf("/sys/dev/block/%u:%u/queue/max_segments",

