                AVIStream *avist       = s->streams[n]->priv_data;



                if (par->codec_type == AVMEDIA_TYPE_VIDEO) {

                    if (nb_frames < avist->packet_count)

                        nb_frames = avist->packet_count;

                } else {

                    if (par->codec_id == AV_CODEC_ID_MP2 ||

